    int a, b, c;
    int d, e;
    int n;

    // Read input
    scanf("%d %d %d", &a, &b, &c);
    scanf("%d %d", &d, &e);
    scanf("%d", &n);

    // Count DVDs of each type
    int count_old = 0, count_new = 0, count_recent = 0;
    char type[10];

    for (int i = 0; i < n; i++) {
        scanf("%s", type);
        if (strcmp(type, "old") == 0) {
            count_old++;
        } else if (strcmp(type, "new") == 0) {
            count_new++;
        } else if (strcmp(type, "recent") == 0) {
            count_recent++;
        }
    }

    // Create array of all individual DVD prices
    int prices[MAX_N];
    int idx = 0;

    for (int i = 0; i < count_old; i++) {
        prices[idx++] = a;
    }
    for (int i = 0; i < count_new; i++) {
        prices[idx++] = b;
    }
    for (int i = 0; i < count_recent; i++) {
        prices[idx++] = c;
    }

    // Sort prices in ascending order
    qsort(prices, n, sizeof(int), cmp);

    long long total = 0;
    int remaining = n;
    int pos = 0; // current position in sorted prices

    // Try to apply set rentals greedily
    // The optimal strategy is to use set rentals on the most expensive DVDs

    while (remaining > 0) {
        // Calculate regular price of current cheapest remaining
        // Actually we need to check if applying a set rental is beneficial
        // We'll check from the most expensive side

        if (remaining >= d) {
            // Calculate sum of d most expensive DVDs
            long long sum_expensive = 0;
            for (int i = remaining - d; i < remaining; i++) {
                sum_expensive += prices[i];
            }

            // If set rental is cheaper, apply it
            if (sum_expensive > (long long)d * e) {
                total += (long long)d * e;
                remaining -= d;
                continue;
            }
        } else {
            // remaining < d
            // Calculate sum of all remaining DVDs
            long long sum_all = 0;
            for (int i = 0; i < remaining; i++) {
                sum_all += prices[i];
            }

            // If can apply set rental for d DVDs even though we have fewer
            if (sum_all > (long long)d * e) {
                total += (long long)d * e;
                remaining = 0;
                continue;
            }
        }

        // If no set rental applies, take the cheapest remaining DVD at regular price
        total += prices[pos];
        pos++;
        remaining--;
    }

    printf("%lld\n", total);

    return 0;
}

