            int cnt = xa + xb + xc;
            int reg = xa * a + xb * b + xc * c;
            int setCost = (cnt >= d) ? cnt * e : d * e;
            int groupCost = (reg > setCost) ? setCost : reg;
            int total = groupCost + solve(na - xa, nb - xb, nc - xc);
            if (total < best) best = total;
        }
        memo.put(key, best);
        return best;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        long a = fs.nextLong();
        long b = fs.nextLong();
        long c = fs.nextLong();
        int d = fs.nextInt();
        long e = fs.nextLong();

        int x = fs.nextInt(); // old movies
        int y = fs.nextInt(); // new releases
        int z = fs.nextInt(); // recent releases

        long[] dp = new long[x + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 4);
        dp[0] = 0;

        // Process old movies
        for (int i = 0; i < x; i++) {
            long[] ndp = new long[x + 1];
            Arrays.fill(ndp, Long.MAX_VALUE / 4);
            for (int used = 0; used <= i; used++) {
                long cur = dp[used];
                if (cur >= Long.MAX_VALUE / 8) continue;

                // Rent normally
                ndp[used] = Math.min(ndp[used], cur + a);

                // Start a package with this old movie and greedily fill with most expensive remaining DVDs
                int takeRecent = z;
                int takeNew = y;
                int takeOld = x - i; // includes current DVD

                for (int k = 1; k <= takeOld + takeNew + takeRecent; k++) {
                    long regular = 0;
                    int rr = Math.min(k, takeRecent);
                    regular += (long) rr * c;
                    int rem = k - rr;

                    int nn = Math.min(rem, takeNew);
                    regular += (long) nn * b;
                    rem -= nn;

                    int oo = rem;
                    regular += (long) oo * a;

                    long packCost;
                    if (k >= d) packCost = Math.min(regular, (long) k * e);
                    else packCost = Math.min(regular, (long) d * e);

                    int oldUsedInPackage = oo;
                    if (oldUsedInPackage >= 1) {
                        ndp[used + oldUsedInPackage] = Math.min(ndp[used + oldUsedInPackage], cur + packCost);
                    }
                }
            }
            dp = ndp;
        }

        // Add all non-old DVDs normally first
        long base = (long) y * b + (long) z * c;
        long ans = Long.MAX_VALUE / 4;
        for (int usedOld = 0; usedOld <= x; usedOld++) {
            ans = Math.min(ans, dp[usedOld] + base);
        }

        /*
         The above DP is not sufficient because packages can mix all categories arbitrarily.
         Since there are only 3 price types, we can solve directly by enumerating how many DVDs
         are rented in total under packages. For any chosen counts (i,j,k), package cost depends only
         on total count and total regular price, and optimal package uses most expensive DVDs first.
        */

        // Build prefix sums of most expensive DVDs
        int n = x + y + z;
        long[] pref = new long[n + 1];
        int idx = 0;
        for (int i = 0; i < z; i++) pref[++idx] = pref[idx - 1] + c;
        for (int i = 0; i < y; i++) pref[++idx] = pref[idx - 1] + b;
        for (int i = 0; i < x; i++) pref[++idx] = pref[idx - 1] + a;

        long totalRegular = pref[n];
        long[] best = new long[n + 1];
        for (int t = 0; t <= n; t++) {
            long reg = pref[t];
            long cost;
            if (t == 0) cost = 0;
            else if (t >= d) cost = Math.min(reg, (long) t * e);
            else cost = Math.min(reg, (long) d * e);
            best[t] = cost;
        }

        // Unbounded application of set rentals over prefixes:
        long[] f = new long[n + 1];
        Arrays.fill(f, Long.MAX_VALUE / 4);
        f[0] = 0;
        for (int i = 1; i <= n; i++) {
            // last package takes top t among remaining expensive DVDs -> equivalent to partition of prefix
            for (int t = 1; t <= i; t++) {
                long regSegment = pref[i] - pref[i - t];
                long segCost;
                if (t >= d) segCost = Math.min(regSegment, (long) t * e);
                else segCost = Math.min(regSegment, (long) d * e);
                f[i] = Math.min(f[i], f[i - t] + segCost);
            }
        }

        // Remaining DVDs (cheaper suffix) are regular, but since partition of all DVDs is allowed, answer is f[n]
        System.out.println(f[n]);
    }
}
